Console.WriteLine("Tulemus salvestatud!");
</code></pre> <pre><code>using System.IO;

namespace FilesApp;

class Program
{
    static void Main(string[] args)
    {
        Console.Write("Sisesta mängija nimi: ");
        string nimi = Console.ReadLine();

        Console.Write("Sisesta punktid: ");
